// Single line, tab-separated like /wifi_networks.txt - the ESP32 needs
// structured read/write here too, and a hand-rolled format again avoids
// pulling in a JSON library just for this (ArduinoJson is only added here
// for talking to Brewfather's actual API responses).
bool loadBrewfatherSettings(String &userId, String &apiKey) {
  File f = SPIFFS.open(BREWFATHER_SETTINGS_FILE, FILE_READ);
  if (!f) return false;
  String line = f.readStringUntil('\n');
  f.close();
  if (line.length() > 0 && line.charAt(line.length() - 1) == '\r') {
    line.remove(line.length() - 1);
  }
  int tabIdx = line.indexOf('\t');
  if (tabIdx < 0) return false;
  userId = line.substring(0, tabIdx);
  apiKey = line.substring(tabIdx + 1);
  return userId.length() > 0 && apiKey.length() > 0;
}

bool saveBrewfatherSettings(const String &userId, const String &apiKey) {
  File f = SPIFFS.open(BREWFATHER_SETTINGS_FILE, FILE_WRITE);
  if (!f) return false;
  f.print(userId);
  f.print('\t');
  f.print(apiKey);
  f.print('\n');
  f.close();
  return true;
}

// ── Async fetch job ──
// An HTTPS request + JSON parse can take multiple seconds - doing that
// inside an HTTP handler (which runs on server.handleClient(), on the same
// core/loop as the WebSocket and sensor reads) would starve them exactly
// like the blocking sensor reads once starved the WebSocket handshake (see
// pumpNetwork()). So this runs on its own FreeRTOS task, pinned to the
// other core (see brewfatherTask()/setup()) - the main loop's core is
// never touched by it at all, not even briefly.
//
// Only one job is ever in flight, so plain shared globals are used instead
// of a mutex - same accepted-risk pattern as sharedLine0/sharedLine1 for
// the LCD. The HTTP handler sets brewfatherBusy=true BEFORE handing off a
// request, and only reads brewfatherResultJson/brewfatherError AFTER
// observing brewfatherBusy==false; the task only writes those two AND THEN
// clears brewfatherBusy as its last step. That ordering is what makes this
// safe without a lock, not the volatile qualifier alone.
volatile bool brewfatherBusy = false;
volatile bool brewfatherRequestPending = false;
int brewfatherRequestType = 0; // 1 = recipe list, 2 = one recipe's detail
String brewfatherRequestId = "";
String brewfatherResultJson = "";
String brewfatherError = "";

bool brewfatherHttpsGet(const String &path, String &responseBody, String &errorOut) {
  String userId, apiKey;
  if (!loadBrewfatherSettings(userId, apiKey)) {
    errorOut = "Brewfather is not configured.";
    return false;
  }
  WiFiClientSecure client;
  client.setCACert(BREWFATHER_ROOT_CA);
  HTTPClient https;
  String url = "https://api.brewfather.app" + path;
  if (!https.begin(client, url)) {
    errorOut = "Could not start the request.";
    return false;
  }
  https.setTimeout(15000);
  https.addHeader("Authorization", "Basic " + base64::encode(userId + ":" + apiKey));
  Serial.print("[brewfather] GET ");
  Serial.print(path);
  Serial.println(" ...");
  unsigned long t0 = millis();
  int code = https.GET();
  Serial.print("[brewfather] HTTP ");
  Serial.print(code);
  Serial.print(" after ");
  Serial.print(millis() - t0);
  Serial.println("ms");
  bool ok = false;
  if (code == 200) {
    responseBody = https.getString();
    Serial.print("[brewfather] response body length: ");
    Serial.println(responseBody.length());
    ok = true;
  } else if (code == 401) {
    errorOut = "Brewfather rejected the User ID/API Key.";
  } else if (code == 429) {
    errorOut = "Brewfather's rate limit was reached - try again later.";
  } else if (code > 0) {
    errorOut = "Brewfather returned HTTP " + String(code);
  } else {
    errorOut = "Network error: " + https.errorToString(code);
    Serial.print("[brewfather] errorToString: ");
    Serial.println(https.errorToString(code));
  }
  https.end();
  return ok;
}

// Only the lightweight {id, name} pair per recipe - the list screen never
// needs a full recipe, only what's picked from it (see
// fetchBrewfatherRecipeDetail()).
bool fetchBrewfatherRecipeList() {
  String body, err;
  if (!brewfatherHttpsGet("/v2/recipes?limit=50", body, err)) {
    brewfatherError = err;
    return false;
  }
  JsonDocument inDoc;
  DeserializationError parseErr = deserializeJson(inDoc, body);
  if (parseErr) {
    brewfatherError = "Could not parse Brewfather's response.";
    Serial.print("[brewfather] list JSON parse error: ");
    Serial.println(parseErr.c_str());
    return false;
  }
  JsonDocument outDoc;
  JsonArray outArr = outDoc.to<JsonArray>();
  for (JsonObject item : inDoc.as<JsonArray>()) {
    JsonObject entry = outArr.add<JsonObject>();
    entry["id"] = item["_id"].as<String>();
    entry["name"] = item["name"].as<String>();
  }
  brewfatherResultJson = "";
  serializeJson(outDoc, brewfatherResultJson);
  Serial.print("[brewfather] list ok, ");
  Serial.print(outArr.size());
  Serial.println(" recipes");
  return true;
}

// Passes Brewfather's recipe JSON straight through to the browser,
// essentially unchanged - deliberately NOT hand-mapping individual fields
// into a fixed schema here. An earlier version of this function did
// exactly that (picking out name/og/ibu/abv/mash/hops one by one) and it
// silently dropped everything else Brewfather actually returns - timing,
// water, other ingredients, notes - because nobody had added them to the
// list. That is the exact same class of bug already hit once with
// BeerXML, and the fix there was the same fix as here: let the browser
// walk the WHOLE tree generically (see collectAllFields() in ys-boot.html
// for the BeerXML/XML version, mapBrewfatherRecipe()/
// collectAllFieldsFromJson() for this JSON version) instead of trusting a
// hand-picked field list on this end. The ESP32's only job is fetching
// the JSON and confirming it's well-formed before forwarding it - not
// deciding which of its fields matter.
bool fetchBrewfatherRecipeDetail(const String &id) {
  String body, err;
  if (!brewfatherHttpsGet("/v2/recipes/" + id, body, err)) {
    brewfatherError = err;
    return false;
  }
  JsonDocument doc;
  DeserializationError parseErr = deserializeJson(doc, body);
  if (parseErr) {
    brewfatherError = "Could not parse Brewfather's response.";
    Serial.print("[brewfather] recipe JSON parse error: ");
    Serial.println(parseErr.c_str());
    return false;
  }
  brewfatherResultJson = body;
  Serial.print("[brewfather] recipe detail ok: \"");
  Serial.print(doc["name"].as<String>());
  Serial.print("\" (");
  Serial.print(body.length());
  Serial.print(" bytes, passed through as-is, free heap: ");
  Serial.print(ESP.getFreeHeap());
  Serial.println(")");
  return true;
}

void brewfatherTask(void *param) {
  for (;;) {
    if (brewfatherRequestPending) {
      int type = brewfatherRequestType;
      String id = brewfatherRequestId;
      brewfatherRequestPending = false;
      brewfatherError = "";
      if (type == 1) {
        fetchBrewfatherRecipeList();
      } else if (type == 2) {
        fetchBrewfatherRecipeDetail(id);
      }
      brewfatherBusy = false;
    }
    vTaskDelay(pdMS_TO_TICKS(200));
  }
}

void handleBrewfatherSettingsGet() {
  String userId, apiKey;
  bool configured = loadBrewfatherSettings(userId, apiKey);
  JsonDocument doc;
  doc["configured"] = configured;
  doc["user_id"] = configured ? userId : "";
  String out;
  serializeJson(doc, out);
  server.send(200, "application/json", out);
}

void handleBrewfatherSettingsSave() {
  String userId = server.arg("user_id");
  String apiKey = server.arg("api_key");
  if (userId.length() == 0 || userId.length() > 64 ||
      userId.indexOf('\t') != -1 || userId.indexOf('\n') != -1 || userId.indexOf('\r') != -1) {
    server.send(400, "application/json", "{\"error\":\"Invalid User ID.\"}");
    return;
  }
  if (apiKey.length() == 0 || apiKey.length() > 128 ||
      apiKey.indexOf('\t') != -1 || apiKey.indexOf('\n') != -1 || apiKey.indexOf('\r') != -1) {
    server.send(400, "application/json", "{\"error\":\"Invalid API Key.\"}");
    return;
  }
  if (!saveBrewfatherSettings(userId, apiKey)) {
    server.send(500, "application/json", "{\"error\":\"Could not save settings.\"}");
    return;
  }
  server.send(200, "application/json", "{\"ok\":true}");
}

void handleBrewfatherFetchList() {
  if (brewfatherBusy) {
    server.send(409, "application/json", "{\"error\":\"A request is already in progress.\"}");
    return;
  }
  String userId, apiKey;
  if (!loadBrewfatherSettings(userId, apiKey)) {
    server.send(400, "application/json", "{\"error\":\"Brewfather is not configured.\"}");
    return;
  }
  brewfatherBusy = true;
  brewfatherRequestType = 1;
  brewfatherRequestId = "";
  brewfatherRequestPending = true;
  server.send(200, "application/json", "{\"ok\":true}");
}

void handleBrewfatherFetchRecipe() {
  if (brewfatherBusy) {
    server.send(409, "application/json", "{\"error\":\"A request is already in progress.\"}");
    return;
  }
  String id = server.arg("id");
  if (id.length() == 0 || id.length() > 64) {
    server.send(400, "application/json", "{\"error\":\"Invalid recipe id.\"}");
    return;
  }
  String userId, apiKey;
  if (!loadBrewfatherSettings(userId, apiKey)) {
    server.send(400, "application/json", "{\"error\":\"Brewfather is not configured.\"}");
    return;
  }
  brewfatherBusy = true;
  brewfatherRequestType = 2;
  brewfatherRequestId = id;
  brewfatherRequestPending = true;
  server.send(200, "application/json", "{\"ok\":true}");
}

void handleBrewfatherStatus() {
  if (brewfatherBusy) {
    server.send(200, "application/json", "{\"busy\":true,\"error\":null,\"result\":null}");
    return;
  }
  if (brewfatherError.length() > 0) {
    JsonDocument doc;
    doc["busy"] = false;
    doc["error"] = brewfatherError;
    doc["result"] = nullptr;
    String out;
    serializeJson(doc, out);
    server.send(200, "application/json", out);
    return;
  }
  if (brewfatherResultJson.length() > 0) {
    // Streamed in three pieces instead of building one combined String via
    // serialized() - a real Brewfather recipe's full JSON (water/
    // nutrition/equipment included) can be tens of KB, and building
    // {"busy":...,"result":<that whole thing again>} as a second String
    // needs a SECOND same-size contiguous heap block on top of the first
    // (brewfatherResultJson itself, already alive). On an ESP32, heap
    // fragmentation after TLS/WiFi activity makes a ~2x-sized contiguous
    // allocation a real risk - and Arduino's String fails SILENTLY on
    // allocation failure (no exception, no error, just corrupted/
    // truncated content), which would look exactly like "nothing happens"
    // on the phone with no evidence anywhere of what went wrong. This
    // streams the existing string directly instead of ever duplicating it.
    Serial.print("[brewfather] serving status result, free heap: ");
    Serial.println(ESP.getFreeHeap());
    server.setContentLength(CONTENT_LENGTH_UNKNOWN);
    server.send(200, "application/json", "");
    server.sendContent("{\"busy\":false,\"error\":null,\"result\":");
    server.sendContent(brewfatherResultJson);
    server.sendContent("}");
    return;
  }
  server.send(200, "application/json", "{\"busy\":false,\"error\":null,\"result\":null}");
}

void onWsEvent(uint8_t clientNum, WStype_t type, uint8_t *payload, size_t length) {
  switch (type) {
    case WStype_CONNECTED: {
      Serial.printf("[HEAP-DIAG] client %u CONNECTED, free heap = %u bytes\n", clientNum, ESP.getFreeHeap());
      String result = buildBootCheckResultJson();
      webSocket.sendTXT(clientNum, result);
      break;
    }
    case WStype_DISCONNECTED:
      Serial.printf("[HEAP-DIAG] client %u DISCONNECTED, free heap = %u bytes\n", clientNum, ESP.getFreeHeap());
      break;
    case WStype_TEXT: {
      String msg = String((char *)payload).substring(0, length);
      if (msg == "recheck_sensors") {
        runBootCheck();
      } else if (msg == "toggle1") {
        relay1On = !relay1On;
        digitalWrite(RELAY1_PIN, relay1On ? HIGH : LOW);
        String manualJson = buildManualJson();
        webSocket.broadcastTXT(manualJson);
      } else if (msg == "toggle2") {
        relay2On = !relay2On;
        digitalWrite(RELAY2_PIN, relay2On ? HIGH : LOW);
        String manualJson = buildManualJson();
        webSocket.broadcastTXT(manualJson);
      } else if (msg.startsWith("start_control:")) {
        // Manual and CLEAN both send this - see runControlLoop()'s
        // comment for why the server doesn't need to know which screen
        // it came from. Starts safe (off) until the next loop() cycle
        // actually evaluates temp vs. setpoint.
        controlSetpoint = msg.substring(String("start_control:").length()).toFloat();
        controlActive = true;
        ssr1On = false;
        setActiveSSR(SSR_NONE);
        String manualJson = buildManualJson();
        webSocket.broadcastTXT(manualJson);
      } else if (msg == "stop_control") {
        controlActive = false;
        ssr1On = false;
        setActiveSSR(SSR_NONE);
        String manualJson = buildManualJson();
        webSocket.broadcastTXT(manualJson);
      } else if (msg.startsWith("start_boil_control:")) {
        // Separate from start_control above on purpose - this one is
        // SSR2/Boil over PT100 B (see runBoilControlLoop(), DECISIONS.md),
        // the Boil brew stage is the only sender so far.
        controlSetpointBoil = msg.substring(String("start_boil_control:").length()).toFloat();
        controlActiveBoil = true;
        ssr2On = false;
        setActiveSSR(SSR_NONE);
        String manualJson = buildManualJson();
        webSocket.broadcastTXT(manualJson);
      } else if (msg == "stop_boil_control") {
        controlActiveBoil = false;
        ssr2On = false;
        setActiveSSR(SSR_NONE);
        String manualJson = buildManualJson();
        webSocket.broadcastTXT(manualJson);
      }
      // Any other text is silently ignored - unrecognised commands must
      // never be guessed at, only known-safe ones act on the relays.
      break;
    }
    default:
      break;
  }
}

// 2026-09-03: setup() hung forever inside scanForLcd() - the Wire driver's
// beginTransmission()/endTransmission() never returned, meaning SDA (or
// SCL) was physically stuck rather than just unanswered. That happens when
// a device loses power mid-transaction and its output stage keeps sinking
// the line low. The standard fix: bit-bang up to 9 SCL pulses before
// Wire.begin() ever touches the bus, which gives a stuck slave enough
// clocks to finish its byte and release SDA, then issue a manual STOP.
void i2cBusRecovery() {
  pinMode(PIN_SDA, INPUT_PULLUP);
  pinMode(PIN_SCL, OUTPUT);
  digitalWrite(PIN_SCL, HIGH);
  delayMicroseconds(5);

  for (int i = 0; i < 9 && digitalRead(PIN_SDA) == LOW; i++) {
    digitalWrite(PIN_SCL, LOW);
    delayMicroseconds(5);
    digitalWrite(PIN_SCL, HIGH);
    delayMicroseconds(5);
  }

  // Manual STOP: SDA low->high while SCL is high.
  pinMode(PIN_SDA, OUTPUT);
  digitalWrite(PIN_SDA, LOW);
  delayMicroseconds(5);
  digitalWrite(PIN_SCL, HIGH);
  delayMicroseconds(5);
  digitalWrite(PIN_SDA, HIGH);
  delayMicroseconds(5);
}

uint8_t scanForLcd() {
  for (uint8_t addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    if (Wire.endTransmission() == 0) return addr;
  }
  return 0;
}

// --- LCD health --------------------------------------------------------
// LiquidCrystal_I2C never checks for an ACK, so a display that has dropped
// off the bus keeps showing its last frame and nothing reports it. The scan
// used to run once in setup(), which meant an LCD that was not answering at
// that instant was never written to again. Poll it instead, and rebuild the
// driver whenever it comes back.
uint32_t lcdReinits = 0;
uint16_t lcdFails = 0;
unsigned long lastLcdCheckMs = 0;

bool lcdAcks() {
  if (!lcdAddress) return false;
  Wire.beginTransmission(lcdAddress);
  return Wire.endTransmission() == 0;
}

void initLcd() {
  if (lcd) {
    delete lcd;
    lcd = nullptr;
  }
  lcd = new LiquidCrystal_I2C(lcdAddress, LCD_COLS, LCD_ROWS);
  lcd->init();
  delay(50);
  lcd->init();
  lcd->backlight();
  lcd->clear();
}

// Set only here, once a second - loop() reads this instead of calling
// lcdAcks() again itself, which used to fire an extra I2C transaction every
// 200ms regardless of this function's once-a-second gate.
bool lastLcdAck = false;

void serviceLcd() {
#if !LCD_ENABLED
  return;
#endif
  if (millis() - lastLcdCheckMs < 1000) return;
  lastLcdCheckMs = millis();

  if (!lcdAddress) {
    lastLcdAck = false;
    lcdAddress = scanForLcd();
    if (lcdAddress) {
      initLcd();
      lcdReinits++;
      Serial.print("LCD appeared at 0x");
      Serial.println(lcdAddress, HEX);
    }
    return;
  }

  lastLcdAck = lcdAcks();
  if (lastLcdAck) {
    lcdFails = 0;
    return;
  }

  lcdFails++;
  if (lcdFails >= 3) {
    lcdFails = 0;
    uint8_t addr = scanForLcd();
    if (addr) {
      lcdAddress = addr;
      initLcd();
      lcdReinits++;
      lastLcdAck = true;
      Serial.print("LCD recovered at 0x");
      Serial.println(lcdAddress, HEX);
    }
  }
}

// Fixed width so leftovers from a longer previous line never linger.
// Pads/truncates in place on a fixed buffer - no String, no heap churn.
void lcdLine(uint8_t row, const char *text) {
  if (!lcd) return;
  char padded[LCD_COLS + 1];
  size_t i = 0;
  for (; i < LCD_COLS && text[i] != '\0'; i++) padded[i] = text[i];
  for (; i < LCD_COLS; i++) padded[i] = ' ';
  padded[LCD_COLS] = '\0';
  lcd->setCursor(0, row);
  lcd->print(padded);
}

// Owns every Wire/LCD call, on its own FreeRTOS task. If the I2C bus locks
// up inside serviceLcd() or lcdLine() - which has happened, and survived
// both a manual bus-recovery sequence and Wire.setTimeOut() - this task
// blocks forever, but it is the *only* thing that blocks. loop() (sensors,
// SSR, the watchdog reset) keeps running on its own task, completely
// unaffected, for as long as it takes to notice and fix the LCD for real.
void lcdTask(void *param) {
  i2cBusRecovery();
  Wire.begin(PIN_SDA, PIN_SCL);
  Wire.setTimeOut(50); // ms - best effort; task isolation is the real fix
  lcdAddress = scanForLcd();
  if (lcdAddress) {
    initLcd();
    Serial.print("LCD at 0x");
    Serial.println(lcdAddress, HEX);
  } else {
    Serial.println("LCD NOT FOUND at boot - will keep retrying every second");
  }

  for (;;) {
    serviceLcd();
    lcdLine(0, sharedLine0);
    lcdLine(1, sharedLine1);
    vTaskDelay(pdMS_TO_TICKS(200));
  }
}

void setup() {
  Serial.begin(115200);
  delay(1000);
  bootCount++;
  Serial.print("[boot] start, bootCount=");
  Serial.println(bootCount);

  // Both SSRs forced off before anything else, including anything below
  // that could hang (I2C scan on a stuck bus, e.g.) - a hang must never
  // leave either one live. Pins are configured directly here (setActiveSSR
  // assumes OUTPUT mode is already set); after this, every SSR write goes
  // through setActiveSSR(), never a raw digitalWrite on these two pins.
  pinMode(SSR_PIN, OUTPUT);
  pinMode(SSR2_PIN, OUTPUT);
  setActiveSSR(SSR_NONE); // LOW = SSR off, direct-drive, normal polarity
  pinMode(RELAY1_PIN, OUTPUT);
  pinMode(RELAY2_PIN, OUTPUT);
  // 2026-09-05: latched off permanently, not just at boot. Wiring already
  // confirmed good (see notes/session-2026-09-04-summary.md 6c) - nothing
  // in loop() writes to these pins again until a UI-driven decision to
  // turn them on exists.
  digitalWrite(RELAY1_PIN, LOW); // LOW = off, HIGH-level trigger modules
  digitalWrite(RELAY2_PIN, LOW);

  // 2026-09-03: setup() hung indefinitely in the I2C scan after a wiring
  // change left the bus in a bad state - the SSR stayed stuck ON the whole
  // time because nothing was left running to turn it off. A hardware
  // watchdog forces a full reset (which re-runs the digitalWrite above)
  // if loop() - or setup() itself - ever fails to check in within 10s.
  esp_task_wdt_init(10, true); // 10s timeout, panic (reset) on expiry
  esp_task_wdt_add(NULL);
  Serial.println("[boot] watchdog armed, SSR forced off");

  pinMode(CS_A, OUTPUT);
  pinMode(CS_B, OUTPUT);
  digitalWrite(CS_A, HIGH);
  digitalWrite(CS_B, HIGH);

  Serial.println("[boot] CS pins set");

  pt100_a.begin(WIRES);
  Serial.println("[boot] pt100_a.begin done");
  pt100_b.begin(WIRES);
  Serial.println("[boot] pt100_b.begin done");

#if LCD_ENABLED
  // Runs on its own task (see lcdTask) so a hang here can never stop this
  // function from returning, or block loop() from ever starting.
  xTaskCreatePinnedToCore(lcdTask, "lcdTask", 4096, NULL, 1, NULL, 0);
  Serial.println("[boot] lcdTask started on core 0");
#else
  Serial.println("[boot] LCD_ENABLED=0 - skipping Wire/LCD entirely");
#endif

  Serial.println("2x PT100 + LCD + SSR1 (P32, Manual/CLEAN on/off control)");

  // Own task, own core - an HTTPS call + JSON parse must never run on the
  // same core/loop as server.handleClient()/webSocket.loop() (see the
  // brewfatherTask() comment for why). 12KB stack: mbedTLS's handshake is
  // stack-hungry and this task doesn't share loopTask's larger default.
  xTaskCreatePinnedToCore(brewfatherTask, "brewfatherTask", 12288, NULL, 1, NULL, 0);
  Serial.println("[boot] brewfatherTask started on core 0");

  // WiFi + boot sensor check - see the block above readTemp()/formatSensor()
  // for the reasoning. Runs after everything else in setup() so a WiFi
  // issue can never delay arming the watchdog or starting lcdTask.
  // AP_STA (not just AP) so saved networks (see wifi-setup-screen-spec.md)
  // can be tried as a STA client while SmartBrew-Test keeps running - both
  // proven stable together on real hardware in ap_sta_test.cpp.
  WiFi.mode(WIFI_AP_STA);
  WiFi.softAP(AP_SSID, AP_PASSWORD);
  Serial.print("[boot] AP started: \"");
  Serial.print(AP_SSID);
  Serial.println("\"");
  Serial.print("[boot] http://");
  Serial.println(WiFi.softAPIP());

  // One-time scan feeding findBestChannelForSsid() (see its comment) - the
  // channel a saved STA network is actually on isn't known otherwise, and
  // WiFi.begin(ssid, password) without a channel hint was observed getting
  // stuck at WL_DISCONNECTED indefinitely on this exact hardware/network.
  Serial.println("[wifi-scan] scanning for networks visible to the ESP32...");
  int scanCount = WiFi.scanNetworks();
  if (scanCount <= 0) {
    Serial.println("[wifi-scan] no networks found at all");
  } else {
    for (int i = 0; i < scanCount; i++) {
      Serial.print("[wifi-scan] \"");
      Serial.print(WiFi.SSID(i));
      Serial.print("\" rssi=");
      Serial.print(WiFi.RSSI(i));
      Serial.print("dBm channel=");
      Serial.println(WiFi.channel(i));
      if (bootScanResultCount < MAX_BOOT_SCAN_RESULTS) {
        bootScanResults[bootScanResultCount].ssid = WiFi.SSID(i);
        bootScanResults[bootScanResultCount].channel = WiFi.channel(i);
        bootScanResults[bootScanResultCount].rssi = WiFi.RSSI(i);
        bootScanResultCount++;
      }
    }
  }
  WiFi.scanDelete();

  // true = format on first use / if mount fails, so a fresh or corrupted
  // partition doesn't leave saved-recipe routes silently broken forever.
  if (SPIFFS.begin(true)) {
    Serial.print("[boot] SPIFFS mounted, ");
    Serial.print(SPIFFS.usedBytes());
    Serial.print("/");
    Serial.print(SPIFFS.totalBytes());
    Serial.println(" bytes used");
  } else {
    Serial.println("[boot] SPIFFS mount FAILED - save/load recipe will not work");
  }

  server.on("/", handleRoot);
  server.on("/ys-logo-full.png", handleLogoFull);
  server.on("/ys-logo-topbar.png", handleLogoTopbar);
  server.on("/save_recipe", HTTP_POST, handleSaveRecipe);
  server.on("/list_recipes", HTTP_GET, handleListRecipes);
  server.on("/load_recipe", HTTP_GET, handleLoadRecipe);
  server.on("/list_wifi", HTTP_GET, handleListWifi);
  server.on("/add_wifi", HTTP_POST, handleAddWifi);
  server.on("/delete_wifi", HTTP_POST, handleDeleteWifi);
  server.on("/stop_wifi", HTTP_POST, handleStopWifi);
  server.on("/brewfather_settings", HTTP_GET, handleBrewfatherSettingsGet);
  server.on("/brewfather_settings", HTTP_POST, handleBrewfatherSettingsSave);
  server.on("/brewfather_fetch_list", HTTP_POST, handleBrewfatherFetchList);
  server.on("/brewfather_fetch_recipe", HTTP_POST, handleBrewfatherFetchRecipe);
  server.on("/brewfather_status", HTTP_GET, handleBrewfatherStatus);
  server.begin();

  webSocket.begin();
  webSocket.onEvent(onWsEvent);
  // Required for the Manual/CLEAN safety timeout (see runControlLoop()) to
  // actually catch an abrupt disconnect (WiFi dropped, phone locked) and
  // not just a clean tab-close: without this, connectedClients() only
  // reflects whether the TCP socket is still technically open, which can
  // stay "connected" long after the browser is gone.
  //
  // The library starts this ping/pong tracking from the moment a client's
  // raw TCP socket is accepted - BEFORE the WS handshake (HTTP Upgrade)
  // completes - and a client stuck mid-handshake can never register a
  // pong (incoming bytes are only parsed as WS frames, pongs included,
  // once the client has reached WSC_CONNECTED). So a client still
  // upgrading always looks like missed pongs to the heartbeat. This was
  // fatal on real hardware: readRawMedian()'s per-sensor RTD reads (see
  // its comment) starved webSocket.loop() of CPU time long enough that a
  // real handshake took multiple seconds to arrive, long enough for the
  // (then much shorter) heartbeat interval to kill it before it ever
  // finished - stuck boot screen, confirmed via the library's own debug
  // log. That starvation is now fixed at the source (pumpNetwork() calls
  // inside readRawMedian()), so a normal handshake completes in ~1s or
  // less again and this can stay tight: worst case from an actual
  // disconnect to the SSR being cut is ~8s (5s + 1.5s, x2 misses).
  webSocket.enableHeartbeat(5000, 1500, 2);
  Serial.println("[boot] WebSocket server started (port 81)");

  runBootCheck();
}

void loop() {
  esp_task_wdt_reset();
  server.handleClient();
  webSocket.loop();

  // Relays: no service call - they were latched off in setup() and stay
  // that way until an explicit UI-driven decision exists to turn them on.

  float tA = NAN, tB = NAN;
  uint8_t faultA = 0, faultB = 0;
  uint16_t rawA = 0, rawB = 0;
  bool okA = readTemp(pt100_a, CAL_A, healthA, tA, faultA, rawA);
  bool okB = readTemp(pt100_b, CAL_B, healthB, tB, faultB, rawB);

  if (!okA) {
    totalFailsA++;
    unsigned long streak = millis() - lastFailMsA;
    if (streak > longestStreakMsA) longestStreakMsA = streak;
    lastFailMsA = millis();
  }
  if (!okB) {
    totalFailsB++;
    unsigned long streak = millis() - lastFailMsB;
    if (streak > longestStreakMsB) longestStreakMsB = streak;
    lastFailMsB = millis();
  }

  // Manual/CLEAN bang-bang control - after the sensor read (needs this
  // cycle's freshness/value) but before the periodic "manual" broadcast
  // below, so a state change this cycle is reflected in that same push
  // rather than waiting up to another second.
  runControlLoop(okA, tA);
  runBoilControlLoop(okB, tB);

  if (millis() - lastManualPushMs >= MANUAL_PUSH_MS) {
    lastManualPushMs = millis();
    String manualJson = buildManualJson();
    webSocket.broadcastTXT(manualJson);
  }

  // Gated to ~1/s, not every loop() iteration - it reads a SPIFFS file
  // each call, which is unnecessary work at the ~1.5Hz loop() already
  // runs and irrelevant at STA-connection-attempt timescales anyway.
  if (millis() - lastStaServiceMs >= 1000UL) {
    lastStaServiceMs = millis();
    serviceStaConnection();
  }

  char s0[24], s1[24], l0[24], l1[24];
  formatSensor(s0, sizeof(s0), "PT1", okA, tA, healthA);
  formatSensor(s1, sizeof(s1), "PT2", okB, tB, healthB);

  // While Manual/CLEAN control is active, the LCD trades the fixed-width
  // marker slot (no longer meaningful - see the SSR cleanup note above)
  // for the setpoint and live SSR state, so the loop is visible on the
  // bench without needing a phone connected. Otherwise unchanged.
  if (controlActive) {
    snprintf(l0, sizeof(l0), "%-9s SP:%4.1f", s0, controlSetpoint);
    snprintf(l1, sizeof(l1), "%-9s SSR:%s", s1, ssr1On ? "ON " : "OFF");
  } else {
    snprintf(l0, sizeof(l0), "%-12s%s", s0, "   ");
    snprintf(l1, sizeof(l1), "%-12s%s", s1, "   ");
  }

  // Hand off to lcdTask() - no Wire/LCD call happens on this task anymore.
  strncpy(sharedLine0, l0, sizeof(sharedLine0) - 1);
  sharedLine0[sizeof(sharedLine0) - 1] = '\0';
  strncpy(sharedLine1, l1, sizeof(sharedLine1) - 1);
  sharedLine1[sizeof(sharedLine1) - 1] = '\0';

  Serial.print("boot=");
  Serial.print(bootCount);
  Serial.print(" up=");
  Serial.print(millis() / 1000);
  Serial.print("s  lcd=0x");
  Serial.print(lcdAddress, HEX);
  Serial.print(lastLcdAck ? " ACK" : " NAK");
  Serial.print(" reinit=");
  Serial.print(lcdReinits);
  Serial.print("  LCD[0]=\"");
  Serial.print(l0);
  Serial.print("\"  LCD[1]=\"");
  Serial.print(l1);
  Serial.print("\"   A raw=");
  Serial.print(rawA);
  Serial.print(" fault=0x");
  Serial.print(faultA, HEX);
  Serial.print(" fails=");
  Serial.print(healthA.consecFail);
  Serial.print(" reinit=");
  Serial.print(healthA.reinits);
  Serial.print(" | B raw=");
  Serial.print(rawB);
  Serial.print(" fault=0x");
  Serial.print(faultB, HEX);
  Serial.print(" fails=");
  Serial.print(healthB.consecFail);
  Serial.print(" reinit=");
  Serial.print(healthB.reinits);
  Serial.print(" | SSR1=");
  Serial.print(ssr1On ? "ON" : "OFF");
  Serial.print(" ctrl=");
  Serial.print(controlActive ? "ON" : "OFF");
  Serial.print(" SP=");
  Serial.print(controlSetpoint);
  Serial.print(" | SSR2=");
  Serial.print(ssr2On ? "ON" : "OFF");
  Serial.print(" ctrlBoil=");
  Serial.print(controlActiveBoil ? "ON" : "OFF");
  Serial.print(" SPBoil=");
  Serial.print(controlSetpointBoil);
  Serial.print(" | RELAY1=");
  Serial.print(relay1On ? "ON" : "OFF");
  Serial.print(" RELAY2=");
  Serial.println(relay2On ? "ON" : "OFF");

  // Closes the gap between the last pumpNetwork() call inside readTemp()
  // (see readRawMedian()) and here - sensor B's 3rd RTD sample plus all
  // the fail-tracking/control/LCD/Serial-print work above ran with zero
  // network servicing in between.
  pumpNetwork();

  if (millis() - lastSummaryMs >= 60000) {
    lastSummaryMs = millis();
    Serial.print("[summary] boot=");
    Serial.print(bootCount);
    Serial.print(" upSec=");
    Serial.print(millis() / 1000);
    Serial.print(" | A totalFails=");
    Serial.print(totalFailsA);
    Serial.print(" longestGoodStreakSec=");
    Serial.print(longestStreakMsA / 1000);
    Serial.print(" | B totalFails=");
    Serial.print(totalFailsB);
    Serial.print(" longestGoodStreakSec=");
    Serial.println(longestStreakMsB / 1000);
  }

  // 2026-09-04: the scheduled 10-minute self-reset was a soak-test tool for
  // telling "fails cluster near boot" from "fails spread through runtime".
  // Removed - from here on, ANY reboot in the log is a real event worth
  // investigating, not something this firmware caused on purpose.

  // Same ~200ms pacing as before, but serviced in 10ms slices instead of
  // one unbroken delay(200) - that single blocking call was a continuous
  // 200ms hole with zero network servicing, on top of the ~75ms+ tail
  // above it (see pumpNetwork() call just above). Total pacing time is
  // unchanged; only how it's spent is different.
  for (int i = 0; i < 20; i++) {
    delay(10);
    pumpNetwork();
  }
}
